import{_ as i,o as a,c as e,a2 as u}from"./chunks/framework.CdvW4CUT.js";const m=JSON.parse('{"title":"風平浪靜 NagiAsu.xyz 建築比賽 2022/06/27","description":"","frontmatter":{},"headers":[],"relativePath":"web/archive/20220627/index.md","filePath":"web/archive/20220627.md"}'),r={name:"web/archive/20220627/index.md"};function t(o,l,n,h,s,c){return a(),e("div",null,[...l[0]||(l[0]=[u('<h1 id="風平浪靜-nagiasu-xyz-建築比賽-2022-06-27" tabindex="-1">風平浪靜 NagiAsu.xyz 建築比賽 2022/06/27 <a class="header-anchor" href="#風平浪靜-nagiasu-xyz-建築比賽-2022-06-27" aria-label="Permalink to &quot;風平浪靜 NagiAsu.xyz 建築比賽 2022/06/27&quot;">​</a></h1><p>企劃主辦人 : neko_vanilla (香草)</p><h2 id="比賽內容" tabindex="-1">比賽內容 <a class="header-anchor" href="#比賽內容" aria-label="Permalink to &quot;比賽內容&quot;">​</a></h2><ul><li>每位參賽者會以<strong>生存模式</strong>，在範圍為30X30的平地裡(基底為平原草地)，生態域為一般的平原，並以官方提供的材料在限時內進行比賽</li><li>材料為主辦方提供，每人都一樣，比賽開始後開箱子才可得知材料內容，用完不補</li><li>場地大致上是長這樣 30x30，高度不限，旁邊有材料箱子 ![](<a href="https://i.imgur.com/sPEycqs.png" target="_blank" rel="noreferrer">https://i.imgur.com/sPEycqs.png</a> =500x300)</li><li>題材與風格完全由你自由發揮，我們只限制你建材只能使用我們提供給您的</li><li>完成後，請為你自己的建築訂題目與自行想要怎麼說明，箱子內有一本書，請寫在裡面 <ul><li>題目:1-16字內</li><li>說明:1-100字內 <ul><li>字數長度不會直接影響你的分數，所以不用要求自己寫滿，以你認為最有辦法介紹你的題目與建築為主。</li></ul></li></ul></li></ul><h2 id="比賽設定" tabindex="-1">比賽設定 <a class="header-anchor" href="#比賽設定" aria-label="Permalink to &quot;比賽設定&quot;">​</a></h2><ul><li>玩家:生存模式，不可PVP，可自由合成物品，不會飢餓</li><li>世界設定 <ul><li>生態域 : 草地平原 plain</li><li>有日夜與天氣循環</li><li>和平模式</li></ul></li><li>伺服 <ul><li>會提供專用活動伺服，從大廳進入，不同步背包</li></ul></li></ul><h2 id="比賽時間" tabindex="-1">比賽時間 <a class="header-anchor" href="#比賽時間" aria-label="Permalink to &quot;比賽時間&quot;">​</a></h2><ul><li>報名時間: <ul><li>活動開始前10分鐘皆可報名</li></ul></li><li>比賽時間(可建築時間) <ul><li>報到時間 : 2022/06/27(一) 19：00 ~ 19：15 <ul><li>報到完成後，就會立即給你生存權限及建造權，即可直接開始構思建造</li><li>如果趕不上也可以晚點報到，但這就會壓縮到你的參加時間</li></ul></li><li>2022/06/27(一) 19：00 ~ 21：15</li><li>2022/06/28(二) 12：00 ~ 19：00 <ul><li>開始時間可能會視情況調整，但保證至少會有連續六小時</li></ul></li><li>建造時間會保證給你至少2+6小時的可建造時間，但該用多久或何時進來建造則取決於你</li><li>參賽者隨時可自由加入與離開活動場地，但開放時間就只有上述時段，請自行控制時間分配與進度</li></ul></li></ul><h2 id="比賽規則" tabindex="-1">比賽規則 <a class="header-anchor" href="#比賽規則" aria-label="Permalink to &quot;比賽規則&quot;">​</a></h2><ul><li>禁止抄襲他人建築</li><li>請勿搗亂(成立者一律失去比賽資格)</li><li>不可違反伺服與公頻規範，不可有限制級題材</li><li>禁止使用藍圖模組與自動放置</li></ul><h2 id="前三名獎品" tabindex="-1">前三名獎品 <a class="header-anchor" href="#前三名獎品" aria-label="Permalink to &quot;前三名獎品&quot;">​</a></h2><ul><li>第一名 <ul><li>[施工幫] 顏色可由你自選</li><li>遊戲幣70000 <ul><li>(官方20000+香草加碼50000)</li></ul></li></ul></li><li>第二名 <ul><li>[施工幫] 金色</li><li>遊戲幣45000 <ul><li>(官方15000+香草加碼30000)</li></ul></li></ul></li><li>第三名 <ul><li>[施工幫] 白色</li><li>遊戲幣30000 <ul><li>(官方10000+香草加碼20000)</li></ul></li></ul></li><li>第四名~第十名 <ul><li>遊戲幣5000 <ul><li>(香草加碼)</li></ul></li></ul></li><li>稱號注意 : 稱號非永久，將會在下一屆建築比賽進行回收</li></ul><h2 id="基本獎品" tabindex="-1">基本獎品 <a class="header-anchor" href="#基本獎品" aria-label="Permalink to &quot;基本獎品&quot;">​</a></h2><ul><li>完賽 <ul><li>評審認可為完成品的，即可獲得活動紀念品</li><li>參考圖片如下</li><li>![](<a href="https://i.imgur.com/sv9y4Om.png" target="_blank" rel="noreferrer">https://i.imgur.com/sv9y4Om.png</a> =350x250)</li></ul></li><li>參加獎 <ul><li>2000遊戲幣</li><li>極少部分情況，若評審認為這是來亂的或認為完全0分，將不會獲得參加獎</li></ul></li></ul><h2 id="參加資格" tabindex="-1">參加資格 <a class="header-anchor" href="#參加資格" aria-label="Permalink to &quot;參加資格&quot;">​</a></h2><ul><li>加入官方Discord綁定超過七天，與遊玩本伺服超過七天者，即可在Discord活動頻道報名。</li></ul><h2 id="評分方式" tabindex="-1">評分方式 <a class="header-anchor" href="#評分方式" aria-label="Permalink to &quot;評分方式&quot;">​</a></h2><ul><li>由各位評審評分，每位評審會需要參考以下表格來進行評分，最後將各評審之評分加總，依照總分來比較名次。 <ul><li>請尊重各個評審的評分，參賽者不得對評審提出分數異議。</li><li>評審名單會在比賽開始前確定人數與名單，屆時會公告</li></ul></li></ul><h3 id="評分標準如下" tabindex="-1">評分標準如下 <a class="header-anchor" href="#評分標準如下" aria-label="Permalink to &quot;評分標準如下&quot;">​</a></h3><ul><li>美觀 30% <ul><li>看上去舒服，裝飾美觀</li></ul></li><li>結構性 20% <ul><li>結構的合理性與協調性</li></ul></li><li>環境表現 20% <ul><li>地質背影的改造使大局觀更美麗</li></ul></li><li>創意程度 20% <ul><li>天馬行空的幻想及材料的特殊運用</li></ul></li><li>作品介紹文 10% <ul><li>介紹你的作品並敘述你的工法及特色</li></ul></li><li>整體比例 10% <ul><li>以Minecraft人物為準</li></ul></li><li>細緻表現 20% <ul><li>對於你建築上的細部處理方式，主要在接近觀看時的內容表現</li></ul></li><li>彩蛋表現 10% <ul><li>彩蛋內容注意不得影響善良風俗及社會觀感</li></ul></li><li>相似度 10% <ul><li>你的題目是否呼應你所呈現的作品</li></ul></li></ul>',20)])])}const b=i(r,[["render",t]]);export{m as __pageData,b as default};
